WITH customer_summary AS (SELECT customer_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(channel))) AS channel_values, MAX(shipping_fee) - MIN(shipping_fee) AS shipping_fee_range FROM orders GROUP BY customer_id) SELECT c.id, c.signup_date, c.city, cs.channel_values, cs.shipping_fee_range FROM customers c LEFT JOIN customer_summary cs ON c.id = cs.customer_id WHERE cs.shipping_fee_range >= 65 ORDER BY shipping_fee_range
